package com.mohymods.kingdomsmp.profession;
import java.util.*;
import java.util.regex.Pattern;
import net.minecraft.core.*;
import net.minecraft.core.component.DataComponents;
import net.minecraft.server.level.ServerPlayer;
import net.minecraft.world.Container;
import net.minecraft.world.item.*;
import net.minecraft.world.level.block.Blocks;
import com.mohymods.kingdomsmp.placement.PlacementProtection;
/** Readable proposed coordinates are references to current authenticated geometry, never proof by themselves. */
public final class MinePlan {
 public static final String QUEST="kingdom_smp:miner/j08";
 private static final Pattern ROW=Pattern.compile("(access|ore|support)=(-?[0-9]{1,8}),(-?[0-9]{1,4}),(-?[0-9]{1,8})");
 private MinePlan(){}
 public static Map<String,BlockPos> parse(String text){if(text==null||text.length()>32768)throw new IllegalStateException("Keep the mine plan within32768characters");var points=new HashMap<String,BlockPos>();int lines=0;for(String line:text.split("\\R")){if(++lines>256)throw new IllegalStateException("Keep the plan within256lines");var row=ROW.matcher(line.trim());if(row.matches()){if(points.put(row.group(1),new BlockPos(Integer.parseInt(row.group(2)),Integer.parseInt(row.group(3)),Integer.parseInt(row.group(4))))!=null)throw new IllegalStateException("Each mine zone must be listed once");}else if(line.contains("access=")||line.contains("ore=")||line.contains("support="))throw new IllegalStateException("Write zone=x,y,z using whole block coordinates");}if(!points.keySet().equals(Set.of("access","ore","support")))throw new IllegalStateException("Carry a readable book and quill listing access=x,y,z, ore=x,y,z and support=x,y,z on separate lines");var values=new ArrayList<>(points.values());for(int i=0;i<values.size();i++)for(int j=i+1;j<values.size();j++)if(values.get(i).distManhattan(values.get(j))<3)throw new IllegalStateException("Designate separate access, ore and support areas at least three blocks apart");return Map.copyOf(points);}
 public static String validate(ServerPlayer p){var route=MineAccessSavedData.get(p.server).evidence().route(p.getUUID()).orElseThrow();String error="Carry a book and quill with your three mine-zone coordinates";for(int slot=0;slot<36;slot++){var stack=p.getInventory().getItem(slot);if(!stack.is(Items.WRITABLE_BOOK)||stack.getCount()!=1)continue;var book=stack.get(DataComponents.WRITABLE_BOOK_CONTENT);if(book==null||book.pages().isEmpty()||book.pages().size()>20)continue;var text=new StringBuilder();for(var page:book.pages()){text.append(page.raw()).append('\n');if(text.length()>32768)break;}try{var points=parse(text.toString());var entry=BlockPos.of(route.cells().getFirst());if(!points.get("access").equals(entry))throw new IllegalStateException("Access must reference the entrance of your authenticated walked route");if(!route.cells().contains(points.get("support").asLong()))throw new IllegalStateException("Support must reference another retained personally built route block; unknown supports cannot substitute");var ore=points.get("ore");if(Math.abs((long)ore.getX()-entry.getX())>8||Math.abs((long)ore.getY()-entry.getY())>3||Math.abs((long)ore.getZ()-entry.getZ())>8)throw new IllegalStateException("Ore sorting must remain near the recorded entrance");var level=p.serverLevel();for(var point:points.values())if(!level.hasChunkAt(point)||!level.getWorldBorder().isWithinBounds(point)||PlacementProtection.check(level,p,point,point)!=null)throw new IllegalStateException("Current mine zone access or world limits changed");if(!(level.getBlockState(ore).is(Blocks.BARREL)||level.getBlockState(ore).is(Blocks.CHEST))||!(level.getBlockEntity(ore) instanceof Container container))throw new IllegalStateException("Ore area must reference an actual current sorting bin");boolean stocked=false;for(int i=0;i<Math.min(container.getContainerSize(),128);i++){var item=container.getItem(i);if(!item.isEmpty()&&MineInspection.group(net.minecraft.core.registries.BuiltInRegistries.ITEM.getKey(item.getItem()).toString())!=null)stocked=true;}if(!stocked)throw new IllegalStateException("The planned ore sorting area must remain stocked");return java.util.HexFormat.of().formatHex(java.security.MessageDigest.getInstance("SHA-256").digest(text.toString().getBytes(java.nio.charset.StandardCharsets.UTF_8)));}catch(IllegalStateException invalid){error=invalid.getMessage();}catch(java.security.NoSuchAlgorithmException impossible){throw new IllegalStateException(impossible);}}throw new IllegalStateException(error);}
}
